//! Translations keyed by the English source string, in eight languages.
//! The lookup table is generated by `build.rs` from `strings/Localizable.xcstrings`.

use std::sync::atomic::{AtomicU8, Ordering};
use std::time::SystemTime;

use chrono::{Datelike, Timelike};

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Lang {
    En,
    Sv,
    Da,
    Nb,
    Fi,
    De,
    Fr,
    Es,
}

impl Lang {
    const ALL: [Lang; 8] = [
        Lang::En,
        Lang::Sv,
        Lang::Da,
        Lang::Nb,
        Lang::Fi,
        Lang::De,
        Lang::Fr,
        Lang::Es,
    ];

    /// Matches on the language subtag of a locale tag such as `sv-SE` or `nb_NO`.
    pub fn from_locale(tag: &str) -> Lang {
        let primary = tag
            .split(['-', '_'])
            .next()
            .unwrap_or("")
            .to_ascii_lowercase();
        match primary.as_str() {
            "sv" => Lang::Sv,
            "da" => Lang::Da,
            "nb" | "no" => Lang::Nb,
            "fi" => Lang::Fi,
            "de" => Lang::De,
            "fr" => Lang::Fr,
            "es" => Lang::Es,
            _ => Lang::En,
        }
    }
}

static LANG: AtomicU8 = AtomicU8::new(0);

pub fn set_lang(lang: Lang) {
    LANG.store(lang as u8, Ordering::Relaxed);
}

pub fn lang() -> Lang {
    Lang::ALL[LANG.load(Ordering::Relaxed) as usize]
}

include!(concat!(env!("OUT_DIR"), "/strings.rs"));

/// The translation of `source` in the current language, or `source` itself.
pub fn tr(source: &str) -> String {
    lookup(lang(), source).unwrap_or(source).to_string()
}

/// Like [`tr`], then fills in Swift-style format specifiers: `%@`, `%lld`, `%d`
/// take the next argument, `%1$@` the numbered one, and `%%` becomes `%`.
pub fn trf(source: &str, args: &[&str]) -> String {
    let template = lookup(lang(), source).unwrap_or(source);
    let mut out = String::with_capacity(template.len() + 16);
    let mut next = 0;
    let mut chars = template.char_indices().peekable();
    while let Some((i, c)) = chars.next() {
        if c != '%' {
            out.push(c);
            continue;
        }
        let rest = &template[i + 1..];
        if rest.starts_with('%') {
            out.push('%');
            chars.next();
            continue;
        }
        // Positional: digits then `$` then a specifier.
        let digits = rest.chars().take_while(char::is_ascii_digit).count();
        let (index, after) = if digits > 0 && rest[digits..].starts_with('$') {
            (
                rest[..digits].parse::<usize>().ok().map(|n| n - 1),
                digits + 1,
            )
        } else {
            (None, 0)
        };
        let spec = ["@", "lld", "d"]
            .into_iter()
            .find(|s| rest[after..].starts_with(s));
        match spec {
            Some(s) => {
                let idx = index.unwrap_or_else(|| {
                    next += 1;
                    next - 1
                });
                out.push_str(args.get(idx).copied().unwrap_or(""));
                for _ in 0..after + s.len() {
                    chars.next();
                }
            }
            None => out.push('%'),
        }
    }
    out
}

/// The date in the local time zone, as macOS's abbreviated date style shows it in `lang`
/// (`Date.FormatStyle(date: .abbreviated)`): "16 Nov 2026", "16 nov. 2026", "16.11.2026"…
pub fn formatted_date(t: SystemTime, lang: Lang) -> String {
    let d = chrono::DateTime::<chrono::Local>::from(t);
    let (day, month, year) = (d.day(), d.month(), d.year());
    let abbr = |months: [&'static str; 12]| months[month as usize - 1];
    match lang {
        Lang::En => format!(
            "{day} {} {year}",
            abbr([
                "Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec",
            ])
        ),
        Lang::Sv => format!(
            "{day} {} {year}",
            abbr([
                "jan.", "feb.", "mars", "apr.", "maj", "juni", "juli", "aug.", "sep.", "okt.",
                "nov.", "dec.",
            ])
        ),
        Lang::Da => format!(
            "{day}. {} {year}",
            abbr([
                "jan.", "feb.", "mar.", "apr.", "maj", "jun.", "jul.", "aug.", "sep.", "okt.",
                "nov.", "dec.",
            ])
        ),
        Lang::Nb => format!(
            "{day}. {} {year}",
            abbr([
                "jan.", "feb.", "mar.", "apr.", "mai", "jun.", "jul.", "aug.", "sep.", "okt.",
                "nov.", "des.",
            ])
        ),
        Lang::Fi => format!("{day}.{month}.{year}"),
        Lang::De => format!(
            "{day}. {} {year}",
            abbr([
                "Jan.", "Feb.", "März", "Apr.", "Mai", "Juni", "Juli", "Aug.", "Sept.", "Okt.",
                "Nov.", "Dez.",
            ])
        ),
        Lang::Fr => format!(
            "{day} {} {year}",
            abbr([
                "janv.", "févr.", "mars", "avr.", "mai", "juin", "juil.", "août", "sept.", "oct.",
                "nov.", "déc.",
            ])
        ),
        Lang::Es => format!(
            "{day} {} {year}",
            abbr([
                "ene", "feb", "mar", "abr", "may", "jun", "jul", "ago", "sept", "oct", "nov",
                "dic",
            ])
        ),
    }
}

/// [`formatted_date`] followed by the local time as "HH:MM".
pub fn formatted_date_time(t: SystemTime, lang: Lang) -> String {
    let d = chrono::DateTime::<chrono::Local>::from(t);
    format!(
        "{} {:02}:{:02}",
        formatted_date(t, lang),
        d.hour(),
        d.minute()
    )
}
